import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import AdminSidebar from '../../components/AdminSidebar';
import toast from 'react-hot-toast';

const AdminUsersPage = () => {
  const { user, api } = useAuth();
  const navigate = useNavigate();
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [showVerifyModal, setShowVerifyModal] = useState(false);
  const [selectedUser, setSelectedUser] = useState(null);
  const [adminNotes, setAdminNotes] = useState('');

  useEffect(() => {
    if (!user || user.role !== 'admin') {
      navigate('/admin/login');
      return;
    }
    fetchUsers();
  }, [user, navigate]);

  const fetchUsers = async () => {
    try {
      const response = await api.get('/admin/users');
      setUsers(response.data);
    } catch (error) {
      console.error('Error fetching users:', error);
      toast.error('Failed to load users');
    } finally {
      setLoading(false);
    }
  };

  const handleVerify = async (approved) => {
    if (!selectedUser) return;

    try {
      const status = approved ? 'approved' : 'rejected';
      await api.put(`/admin/users/${selectedUser._id}/verify`, {
        isVerified: approved,
        verificationStatus: status,
        verificationNotes: adminNotes
      });

      toast.success(approved ? 'User verified successfully!' : 'User rejected');
      fetchUsers();
      setShowVerifyModal(false);
      setSelectedUser(null);
      setAdminNotes('');
    } catch (error) {
      toast.error('Failed to verify user');
    }
  };

  const handleSuspend = async (userId, currentStatus) => {
    if (window.confirm(`Are you sure you want to ${currentStatus ? 'unsuspend' : 'suspend'} this user?`)) {
      try {
        await api.put(`/admin/users/${userId}/suspend`);
        toast.success(`User ${currentStatus ? 'unsuspended' : 'suspended'} successfully`);
        fetchUsers();
      } catch (error) {
        toast.error('Operation failed');
      }
    }
  };

  const openVerifyModal = (userData) => {
    setSelectedUser(userData);
    setAdminNotes('');
    setShowVerifyModal(true);
  };

  const getVerificationBadge = (userData) => {
    if (userData.verificationStatus === 'approved') {
      return React.createElement('span', { 
        style: { background: '#E0F2E9', color: '#4B7B6E', padding: '4px 12px', borderRadius: '60px', fontSize: '12px', display: 'inline-flex', alignItems: 'center', gap: '6px' }
      }, React.createElement('i', { className: 'fas fa-check-circle' }), ' VERIFIED');
    } else if (userData.verificationStatus === 'rejected') {
      return React.createElement('span', { 
        style: { background: '#FFE5D9', color: '#C27D62', padding: '4px 12px', borderRadius: '60px', fontSize: '12px', display: 'inline-flex', alignItems: 'center', gap: '6px' }
      }, React.createElement('i', { className: 'fas fa-times-circle' }), ' REJECTED');
    } else {
      return React.createElement('span', { 
        style: { background: '#FFF2EB', color: '#E57A5C', padding: '4px 12px', borderRadius: '60px', fontSize: '12px', display: 'inline-flex', alignItems: 'center', gap: '6px' }
      }, React.createElement('i', { className: 'fas fa-clock' }), ' PENDING');
    }
  };

  const filteredUsers = users.filter(u => {
    if (searchTerm && !u.fullName.toLowerCase().includes(searchTerm.toLowerCase()) && 
        !u.email.toLowerCase().includes(searchTerm.toLowerCase())) {
      return false;
    }
    return true;
  });

  const sortedUsers = [...filteredUsers].sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

  if (loading) {
    return React.createElement('div', { style: { display: 'flex' } },
      React.createElement(AdminSidebar),
      React.createElement('div', { style: { flex: 1, padding: '2rem', textAlign: 'center' } }, 'Loading users...')
    );
  }

  return React.createElement('div', { style: { display: 'flex', minHeight: '100vh' } },
    React.createElement(AdminSidebar),
    React.createElement('main', { style: { flex: 1, padding: '2rem', background: '#FFFBF7', overflow: 'auto' } },
      React.createElement('div', { style: { marginBottom: '2rem' } },
        React.createElement('h1', { style: { fontSize: '2rem', background: 'linear-gradient(135deg, #AD8878, #6EA094)', WebkitBackgroundClip: 'text', color: 'transparent', marginBottom: '1rem' } },
          React.createElement('i', { className: 'fas fa-users' }), ' MANAGE USERS'
